1038: /* Delete a range of entries from the listpack. */
1039: unsigned char *lpDeleteRange(unsigned char *lp, long index, unsigned long num) {
1040:     unsigned char *p;
1041:     uint32_t numele = lpGetNumElements(lp);
1042: 
1043:     if (num == 0) return lp; /* Nothing to delete, return ASAP. */
1044:     if ((p = lpSeek(lp, index)) == NULL) return lp;
1045: 
1046:     /* If we know we're gonna delete beyond the end of the listpack, we can just move
1047:      * the EOF marker, and there's no need to iterate through the entries,
1048:      * but if we can't be sure how many entries there are, we rather avoid calling lpLength
1049:      * since that means an additional iteration on all elements.
1050:      *
1051:      * Note that index could overflow, but we use the value after seek, so when we
1052:      * use it no overflow happens. */
1053:     if (numele != LP_HDR_NUMELE_UNKNOWN && index < 0) index = (long)numele + index;
1054:     if (numele != LP_HDR_NUMELE_UNKNOWN && (numele - (unsigned long)index) <= num) {
1055:         p[0] = LP_EOF;
1056:         lpSetTotalBytes(lp, p - lp + 1);
1057:         lpSetNumElements(lp, index);
1058:         lp = lpShrinkToFit(lp);
1059:     } else {
1060:         lp = lpDeleteRangeWithEntry(lp, &p, num);
1061:     }
1062: 
1063:     return lp;
1064: }
