1066: /* Delete the elements 'ps' passed as an array of 'count' element pointers and
1067:  * return the resulting listpack. The elements must be given in the same order
1068:  * as they apper in the listpack. */
1069: unsigned char *lpBatchDelete(unsigned char *lp, unsigned char **ps, unsigned long count) {
1070:     if (count == 0) return lp;
1071:     unsigned char *dst = ps[0];
1072:     size_t total_bytes = lpGetTotalBytes(lp);
1073:     unsigned char *lp_end = lp + total_bytes; /* After the EOF element. */
1074:     assert(lp_end[-1] == LP_EOF);
1075:     /*
1076:      * ----+--------+-----------+--------+---------+-----+---+
1077:      * ... | Delete | Keep      | Delete | Keep    | ... |EOF|
1078:      * ... |xxxxxxxx|           |xxxxxxxx|         | ... |   |
1079:      * ----+--------+-----------+--------+---------+-----+---+
1080:      *     ^        ^           ^                            ^
1081:      *     |        |           |                            |
1082:      *     ps[i]    |           ps[i+1]                      |
1083:      *     skip     keep_start  keep_end                     lp_end
1084:      *
1085:      * The loop memmoves the bytes between keep_start and keep_end to dst.
1086:      */
1087:     for (unsigned long i = 0; i < count; i++) {
1088:         unsigned char *skip = ps[i];
1089:         assert(skip != NULL && skip[0] != LP_EOF);
1090:         unsigned char *keep_start = lpSkip(skip);
1091:         unsigned char *keep_end;
1092:         if (i + 1 < count) {
1093:             keep_end = ps[i + 1];
1094:             /* Deleting consecutive elements. Nothing to keep between them. */
1095:             if (keep_start == keep_end) continue;
1096:         } else {
1097:             /* Keep the rest of the listpack including the EOF marker. */
1098:             keep_end = lp_end;
1099:         }
1100:         assert(keep_end > keep_start);"}

