1801: /*
1802:  * Active expiration of fields in hash
1803:  *
1804:  * Called by hashTypeDbActiveExpire() for each hash registered in the HFE DB
1805:  * (db->hexpires) with an expiration-time less than or equal current time.
1806:  *
1807:  * This callback performs the following actions for each hash:
1808:  * - Delete expired fields as by calling ebExpire(hash)
1809:  * - If afterward there are future fields to expire, it will update the hash in
1810:  *   HFE DB with the next hash-field minimum expiration time by returning
1811:  *   ACT_UPDATE_EXP_ITEM.
1812:  * - If the hash has no more fields to expire, it is removed from the HFE DB
1813:  *   by returning ACT_REMOVE_EXP_ITEM.
1814:  * - If hash has no more fields afterward, it will remove the hash from keyspace.
1815:  */
1816: static ExpireAction hashTypeActiveExpire(eItem _hashObj, void *ctx) {
1817:     robj *hashObj = (robj *) _hashObj;
1818:     ActiveExpireCtx *activeExpireCtx = (ActiveExpireCtx *) ctx;
1819:     sds keystr = NULL;
1820:     ExpireInfo info = {0};
1821: 
1822:     /* If no more quota left for this callback, stop */
1823:     if (activeExpireCtx->fieldsToExpireQuota == 0)
1824:         return ACT_STOP_ACTIVE_EXP;
1825: 
1826:     if (hashObj->encoding == OBJ_ENCODING_LISTPACK_EX) {
1827:         info = (ExpireInfo){
1828:                 .maxToExpire = activeExpireCtx->fieldsToExpireQuota,
1829:                 .ctx = hashObj,
1830:                 .now = commandTimeSnapshot(),
1831:                 .itemsExpired = 0};
1832: 
1833:         listpackExExpire(hashObj, &info);
1834:         server.stat_expired_hash_fields += info.itemsExpired;
1835:         keystr = ((listpackEx*)hashObj->ptr)->key;
1836:     } else {
1837:         serverAssert(hashObj->encoding == OBJ_ENCODING_HT);
1838: 
1839:         dict *d = hashObj->ptr;
1840:         dictExpireMetadata *dictExpireMeta = (dictExpireMetadata *) dictMetadata(d);
1841: 
1842:         info = (ExpireInfo){
1843:                 .maxToExpire = activeExpireCtx->fieldsToExpireQuota,
1844:                 .onExpireItem = onFieldExpire,
1845:                 .ctx = hashObj,
1846:                 .now = commandTimeSnapshot()
1847:         };
1848: 
1849:         ebExpire(&dictExpireMeta->hfe, &hashFieldExpireBucketsType, &info);
1850:         keystr = dictExpireMeta->key;
1851:     }
1852: 
1853:     /* Update quota left */
1854:     activeExpireCtx->fieldsToExpireQuota -= info.itemsExpired;
1855: 
1856:     /* If hash has no more fields to expire, remove it from HFE DB */
1857:     if (info.nextExpireTime == 0) {
1858:         if (hashTypeLength(hashObj, 0) == 0) {
1859:             robj *key = createStringObject(keystr, sdslen(keystr));
1860:             dbDelete(activeExpireCtx->db, key);
1861:             //notifyKeyspaceEvent(NOTIFY_HASH,"xxxxxxxxx",c->argv[1],c->db->id);
1862:             notifyKeyspaceEvent(NOTIFY_GENERIC,"del",key, activeExpireCtx->db->id);
1863:             server.dirty++;
1864:             signalModifiedKey(NULL, &server.db[0], key);
1865:             decrRefCount(key);
1866:         }
1867:         return ACT_REMOVE_EXP_ITEM;
1868:     } else {
1869:         /* Hash has more fields to expire. Keep hash to pending items that will
1870:          * be added back to global HFE DS at the end of ebExpire() */
1871:         ExpireMeta *expireMeta = hashGetExpireMeta(hashObj);
1872:         ebSetMetaExpTime(expireMeta, info.nextExpireTime);
1873:         return ACT_UPDATE_EXP_ITEM;
1874:     }
1875: }
